CREATE VIEW public.regional_state_foundations WITH (security_invoker=true) AS SELECT key AS state_code,value->>'name' AS state_name,value->>'country' AS country,value->>'status' AS availability FROM jsonb_each(public.us_state_catalog());GRANT SELECT ON public.regional_state_foundations TO authenticated,service_role;
CREATE FUNCTION public.regional_geography_rank(_pickup jsonb,_destination jsonb,_areas jsonb,_cross_state boolean,_eligibility boolean,_hours boolean,_gates boolean,_state_only boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE a jsonb;rank integer:=0;label text;BEGIN IF NOT coalesce(_eligibility,false) OR NOT coalesce(_hours,false) OR NOT coalesce(_gates,false) OR _pickup->>'evidence' IS DISTINCT FROM 'authoritative' OR _destination->>'evidence' IS DISTINCT FROM 'authoritative' OR NOT public.us_state_catalog() ? (_pickup->>'state') OR NOT public.us_state_catalog() ? (_destination->>'state') OR jsonb_typeof(_areas) IS DISTINCT FROM 'array' THEN RETURN NULL;END IF;IF _pickup->>'state'<>_destination->>'state' AND (NOT coalesce(_cross_state,false) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(_areas) e WHERE e->>'state'=_destination->>'state')) THEN RETURN NULL;END IF;FOR a IN SELECT value FROM jsonb_array_elements(_areas) LOOP IF a->>'country'='US' AND a->>'state'=_pickup->>'state' THEN IF coalesce(_pickup->>'postalCode','')<>'' AND a->>'postalCode'=_pickup->>'postalCode' THEN rank:=100;label:='ZIP service-area match';EXIT;ELSIF rank<40 AND coalesce(_pickup->>'countyEquivalent','')<>'' AND a->>'countyEquivalent'=_pickup->>'countyEquivalent' AND a->>'countyType'=_pickup->>'countyType' THEN rank:=40;label:='County-equivalent service-area match';ELSIF rank<20 AND _pickup->>'state'='FL' AND _pickup->>'region' IN ('panhandle','northeast','north-central','central','tampa-bay','southwest','southeast') AND a->>'region'=_pickup->>'region' THEN rank:=20;label:='Region service-area match';ELSIF rank<5 AND _state_only THEN rank:=5;label:='State service-area match — not nearby';END IF;END IF;END LOOP;IF rank=0 THEN RETURN NULL;END IF;RETURN jsonb_build_object('rank',rank,'label',label,'nearby',false);END $$;
CREATE OR REPLACE FUNCTION public.pilot_provider_hours(_distribution uuid,_settings jsonb) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.trip_distributions;instant timestamptz;local timestamp;z text;day date;st time;en time;from_at timestamptz;until_at timestamptz;BEGIN SELECT * INTO d FROM public.trip_distributions WHERE id=_distribution;z:=_settings->>'timezone';instant:=public.pilot_local_instant(d.pickup_date,d.pickup_time,d.pickup_timezone);IF instant IS NULL OR z IS NULL THEN RETURN false;END IF;local:=instant AT TIME ZONE z;IF public.pilot_local_instant(local::date,local::time,z) IS NULL THEN RETURN false;END IF;st:=(_settings->>'start')::time;en:=(_settings->>'end')::time;IF st IS NULL OR en IS NULL OR st=en THEN RETURN false;END IF;day:=local::date;IF en<st AND local::time<en THEN day:=day-1;END IF;from_at:=public.pilot_local_instant(day,st,z);until_at:=public.pilot_local_instant(day+CASE WHEN en<st THEN 1 ELSE 0 END,en,z);RETURN from_at IS NOT NULL AND until_at IS NOT NULL AND coalesce(_settings->'days','[]') @> to_jsonb(ARRAY[extract(dow FROM day)::integer]) AND instant>=from_at AND instant<until_at;EXCEPTION WHEN OTHERS THEN RETURN false;END $$;
DO $$ DECLARE body text;BEGIN SELECT pg_get_functiondef(oid) INTO body FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='pilot_scope_reason';IF position('Regional eligibility not configured' IN body)=0 THEN body:=replace(body,'SELECT pickup_zip INTO z FROM public.trips','IF d.pickup_state IS NOT NULL AND d.pickup_state<>''FL'' OR d.destination_state IS NOT NULL AND d.destination_state<>''FL'' THEN RETURN ''Regional eligibility not configured; nationwide matching OFF'';END IF; SELECT pickup_zip INTO z FROM public.trips');EXECUTE body;END IF;
SELECT pg_get_functiondef(oid) INTO body FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='patient_request_snapshot';body:=replace(body,'''pickup_zip'',''dropoff_address''','''pickup_zip'',''pickup_state'',''dropoff_state'',''pickup_county'',''dropoff_county'',''pickup_timezone'',''dropoff_timezone'',''dropoff_address''');EXECUTE body;
SELECT pg_get_functiondef(oid) INTO body FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='selected_trip_export';body:=replace(body,'NOT BETWEEN 1 AND 10','NOT BETWEEN 1 AND 15');body:=replace(body,'''status'',''transport_type''','''status'',''transport_type'',''pickup_state'',''dropoff_state'',''pickup_timezone'',''dropoff_timezone'',''pickup_zip'',''dropoff_zip''');body:=replace(body,'dropoff_city,status,transport_type FROM public.trips','dropoff_city,status,transport_type,pickup_state,dropoff_state,pickup_timezone,dropoff_timezone,pickup_zip,dropoff_zip FROM public.trips');EXECUTE body;
SELECT pg_get_functiondef(oid) INTO body FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='customer_selected_request_export';body:=replace(body,'''destination'',r.dropoff_city','''destination'',r.dropoff_city,''pickup_state'',r.pickup_state,''destination_state'',r.dropoff_state,''pickup_timezone'',r.pickup_timezone,''destination_timezone'',r.dropoff_timezone,''pickup_zip'',r.pickup_zip,''destination_zip'',r.dropoff_zip');body:=replace(body,'''pickup'',''destination'',''service''','''pickup'',''destination'',''pickup_state'',''destination_state'',''pickup_timezone'',''destination_timezone'',''pickup_zip'',''destination_zip'',''service''');EXECUTE body;END $$;
CREATE FUNCTION public.copy_distribution_regional_fields() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.trip_id IS NOT NULL THEN SELECT t.pickup_state,t.dropoff_state,t.dropoff_timezone INTO NEW.pickup_state,NEW.destination_state,NEW.destination_timezone FROM public.trips t WHERE t.id=NEW.trip_id;ELSIF NEW.request_id IS NOT NULL THEN SELECT r.pickup_state,r.dropoff_state,r.dropoff_timezone INTO NEW.pickup_state,NEW.destination_state,NEW.destination_timezone FROM public.ride_requests r WHERE r.id=NEW.request_id;END IF;RETURN NEW;END $$;CREATE TRIGGER copy_new_distribution_regional_fields BEFORE INSERT ON public.trip_distributions FOR EACH ROW EXECUTE FUNCTION public.copy_distribution_regional_fields();